namespace QZoneArchive.Core;
public static partial class ArchiveWriter
{
    private static string BlogHero(ArchiveState state)
    {
        var owner = state.Posts.FirstOrDefault(p => Collector.AuthorId(p) == state.Target) ?? state.Posts.FirstOrDefault();
        var name = owner == null ? state.Target : Collector.AuthorName(owner); if (name == "") name = state.Target;
        return $"""
        <div class='space-top'><b>时光留存 <span>我的离线空间</span></b><span>文字有归处，回忆有回声。</span><a href='#reading-settings'>装扮空间</a></div>
        <div class='space-cover'><span class='cover-star'>✦</span><p>THE DAYS WE KEEP</p><div class='cover-note'>那些普通的日子，<br>也在闪闪发光。</div><span class='cover-orbit'></span></div>
        <div class='space-profile'>{SpaceText.Avatar(state.Target, state)}<div><h1 id='space-title'>{SpaceText.Html(name, state)} 的空间</h1><p>QQ {E(state.Target)} · 私人时光档案 · 本地珍藏</p></div><span class='profile-mark'>✧ MEMORY CLUB</span></div>
        <div class='space-nav'><a href='index.html'>我的说说</a><a href='gallery.html'>光影相册</a><a href='index.html#report'>备份手记</a><button id='random-memory'>偶遇一条回忆 ↗</button></div>
        <details id='reading-settings' class='reading-settings'><summary>阅读与装扮 · 字号 / 行距 / 图片 / 主题</summary><div class='setting-grid'>
        <label>主题<select id='theme'><option value='sky'>晴空蓝</option><option value='paper'>旧信纸</option><option value='night'>夜间空间</option></select></label>
        <label>字号<input id='font-size' type='range' min='13' max='24' value='16'></label><label>行距<input id='line-height' type='range' min='15' max='26' value='20'></label>
        <label>阅读宽度<select id='reading-width'><option value='1100px'>舒适</option><option value='900px'>窄栏长文</option><option value='1400px'>宽屏</option></select></label>
        <label>字体<select id='reading-font'><option value='sans-serif'>清晰黑体</option><option value='serif'>书页宋体</option></select></label>
        <label>图片排版<select id='image-layout'><option value='grid'>九宫格</option><option value='wide'>大图</option><option value='hidden'>纯文字</option></select></label>
        <label>评论<select id='comment-display'><option value='show'>显示评论</option><option value='hide'>隐藏评论</option></select></label>
        <label>本页封面<input id='cover-file' type='file' accept='image/png,image/jpeg,image/webp'></label></div><p>排版偏好保存在此浏览器。封面仅在本次页面打开时使用；不上传图片。</p></details>
        """;
    }
