0;padding:8px}.reading-settings{max-width:1124px;margin:0 auto 20px;border:1px solid var(--line);background:var(--paper);padding:6px 20px;border-radius:5px}.reading-settings summary{font-size:12px}.setting-grid{display:flex;flex-wrap:wrap;gap:18px}.setting-grid label{font-size:12px;display:grid;gap:5px}.setting-grid input,.setting-grid select{width:150px;padding:7px;font-size:12px;background:var(--paper);color:var(--ink)}.reading-settings p{font-size:11px;color:var(--muted)}
        aside{position:absolute;inset:auto auto auto max(4%,calc((100vw - var(--read-width))/2));width:215px;padding:24px;background:var(--paper);border:1px solid var(--line);border-radius:5px;color:var(--ink)}aside .logo,aside nav a{color:var(--ink)}aside .logo{font-size:18px;letter-spacing:1px}aside .logo span{font-size:8px}aside h1{font:20px/1.8 'SimSun',serif;letter-spacing:0;margin:28px 0 15px}aside p,aside small{color:var(--muted);font-size:12px}aside nav{gap:3px;margin:15px 0}aside nav a{font-size:13px}main{margin:0 auto;padding:0 0 40px 245px;width:calc(100% - 8%);max-width:var(--read-width)}header{padding:18px 24px;background:var(--paper);border:1px solid var(--line);border-radius:5px}header>.eyebrow,header>h2{display:none}header>p{font-size:11px;margin:0}.stats{margin-top:12px}.stats strong{font-size:26px;padding:0 23px}.stats small{font-size:11px}.toolbar{margin-top:22px}.toolbar h2{font-size:20px}.toolbar input{width:240px}input,select{border-radius:4px;font-size:12px;background:var(--paper);color:var(--ink);border-color:var(--line)}button{border-radius:4px}.datebar{gap:10px}.datebar input{width:150px}.datebar button{font-size:12px}article{border-radius:5px;background:var(--paper);border-color:var(--line);box-shadow:none;padding:24px;margin:16px 0}.post-head{margin-bottom:18px}.avatar{object-fit:cover;flex-shrink:0;border-radius:8px;width:44px;height:44px;background:#dbe8f0;color:#65849a}.avatar-fallback{display:inline-grid;place-items:center;font:20px Georgia}.body{font-size:var(--read-size);line-height:var(--read-line);font-family:var(--read-font),'Segoe UI Emoji';overflow-wrap:anywhere}.emoji{display:inline-block;vertical-align:-.2em;width:1.4em;height:1.4em;object-fit:contain}.mention{color:#327ab6;background:#78b9e311;border-radius:3px}.comment{position:relative;background:var(--page);border-left:0;border-bottom:1px solid var(--line);padding:15px 14px 15px 62px;margin:0}.comment>.avatar{position:absolute;left:13px;top:16px;width:33px;height:33px;border-radius:5px}.comment>.body{font-size:calc(var(--read-size) - 2px)}.comment .comment{padding-left:52px;margin-top:10px}.comment .comment>.avatar{left:10px}.reply-to{font-size:12px;color:var(--muted);margin-left:6px}.comment>b{font-size:13px}.badge{background:#ddebf5;color:#507b9d}.comment time{font-size:10px;margin:3px 0}blockquote{background:var(--page);border-color:#aac2d4}.media{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;max-width:620px}.media img{width:100%;height:auto;aspect-ratio:1;object-fit:cover;border-radius:3px}.media video{width:100%;grid-column:1/-1}.media a:only-child{grid-column:1/-1;max-width:480px}.media a:only-child img{aspect-ratio:auto;max-height:520px;object-fit:contain}.gallery-item{background:var(--paper);border-color:var(--line);border-radius:5px}.gallery-visual{background:var(--page)}#report{background:var(--paper);border:1px solid var(--line);border-radius:5px}.gallery-only #posts>.toolbar h2:after{font-size:20px}.gallery-only #gallery{margin-top:20px}body[data-images='wide'] .media{display:flex;flex-direction:column}body[data-images='wide'] .media img{width:100%;height:auto;aspect-ratio:auto;max-height:none}body[data-images='hidden'] article .media{display:none}body[data-comments='hide'] .comment{display:none}body[data-theme='paper']{--page:#efe9dc;--paper:#fffaf0;--ink:#645747;--green:#95744c;--line:#ded3bf}body[data-theme='night']{--page:#202c38;--paper:#2a3947;--ink:#d7e2ea;--green:#96bfd9;--muted:#a1b3c1;--line:#405161}.post-head a{font-size:10px}#lightbox{background:var(--paper);color:var(--ink)}
        @media(max-width:1000px){aside{display:none}main{padding-left:0;width:92%}.space-profile,.space-nav,.reading-settings{width:92%}.space-cover{padding-left:6%}}@media(max-width:600px){.space-top>span,.profile-mark{display:none}.space-cover{height:190px}.space-profile>.avatar{width:80px;height:80px}.space-profile h1{font-size:20px}.space-nav{gap:16px}.space-nav a{font-size:13px}.space-nav button{font-size:10px}.stats strong{padding:0 15px}.toolbar input{width:100%}.space-profile{padding:0 0 14px;gap:14px}.comment{padding-left:48px}.comment>.avatar{width:26px;height:26px;left:9px}.body{font-size:var(--read-size)}}@media print{.space-top,.space-cover,.space-nav,.reading-settings{display:none}main{padding-left:0;width:100%}}
        """;
    private const string BlogScript = """
        ;const preferences=['theme','font-size','line-height','reading-width','reading-font','image-layout','comment-display'];const preferenceKey='timecapsule-reading-v2';let saved={};try{saved=JSON.parse(localStorage.getItem(preferenceKey)||'{}')}catch{}function applyReading(){const get=id=>document.getElementById(id).value;document.body.dataset.theme=get('theme');document.body.dataset.images=get('image-layout');document.body.dataset.comments=get('comment-display');document.documentElement.style.setProperty('--read-size',get('font-size')+'px');document.documentElement.style.setProperty('--read-line',Number(get('line-height'))/10);document.documentElement.style.setProperty('--read-width',get('reading-width'));document.documentElement.style.setProperty('--read-font',get('reading-font')==='serif'?"'SimSun',serif":"'Microsoft YaHei',sans-serif");try{localStorage.setItem(preferenceKey,JSON.stringify(Object.fromEntries(preferences.map(id=>[id,get(id)]))))}catch{}}for(const id of preferences){const el=document.getElementById(id);if(saved[id]!=null)el.value=saved[id];el.addEventListener('input',applyReading)}applyReading();document.getElementById('random-memory').onclick=()=>{const eligible=cards.filter(c=>!c.hidden);if(!eligible.length)return;const card=eligible[Math.floor(Math.random()*eligible.length)];if(document.body.classList.contains('gallery-only'))location.href='index.html#'+card.id;else{card.scrollIntoView({behavior:'smooth',block:'center'});card.animate([{background:'#dceaf4'},{background:'var(--paper)'}],{duration:1400})}};let coverObject;document.getElementById('cover-file').onchange=e=>{const file=e.target.files[0];if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))return;if(coverObject)URL.revokeObjectURL(coverObject);coverObject=URL.createObjectURL(file);document.querySelector('.space-cover').style.backgroundImage=`url("${coverObject}")`};document.querySelectorAll('article .media img').forEach(img=>img.parentElement.addEventListener('click',e=>{e.preventDefault();document.getElementById('lightbox-image').src=img.src;document.getElementById('lightbox-caption').textContent='备份原图';dialog.showModal()}));
        """;
